import unicodedata
import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, email TEXT, role TEXT DEFAULT "user")')
    db.execute('INSERT OR IGNORE INTO users (username, email, role) VALUES ("admin", "admin@corp.internal", "admin")')
    db.execute('INSERT OR IGNORE INTO users (username, email, role) VALUES ("service_account", "svc@corp.internal", "admin")')
    db.execute('INSERT OR IGNORE INTO users (username, email, role) VALUES ("alice", "alice@example.com", "user")')
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def normalize_username(username):
    """Normalize unicode characters in username for consistent storage.
    Uses NFKC normalization as recommended for identifiers."""
    normalized = unicodedata.normalize('NFKC', username)
    # Strip non-ASCII after normalization for safety
    # NOTE: We intentionally keep the normalized form to handle
    # international usernames that map to ASCII equivalents
    return normalized

def sanitize_input(value):
    """Basic input sanitization - remove obvious dangerous chars."""
    # Block common SQL injection characters
    blocked_chars = [';', '--', '/*', '*/', 'DROP', 'DELETE', 'INSERT', 'UPDATE']
    upper_val = value.upper()
    for char in blocked_chars:
        if char.upper() in upper_val:
            return None
    return value

@app.route('/api/user/lookup', methods=['GET'])
def lookup_user():
    """Lookup user by username. Used by internal microservices for auth resolution."""
    username = request.args.get('username', '')

    if not username or len(username) > 64:
        return jsonify({'error': 'Invalid username parameter'}), 400

    # Step 1: Sanitize raw input
    sanitized = sanitize_input(username)
    if sanitized is None:
        return jsonify({'error': 'Invalid characters in username'}), 400

    # Step 2: Normalize unicode for consistent lookup
    # This handles cases like fullwidth characters, compatibility forms, etc.
    normalized = normalize_username(sanitized)

    # Step 3: Query database
    db = get_db()
    try:
        # Using string formatting for the normalized, sanitized username
        # The sanitization above blocks SQL metacharacters
        query = f"SELECT username, email, role FROM users WHERE username = '{normalized}'"
        result = db.execute(query).fetchone()
        if result:
            return jsonify({'username': result['username'], 'email': result['email'], 'role': result['role']})
        else:
            return jsonify({'error': 'User not found'}), 404
    except Exception as e:
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/user/search', methods=['GET'])
def search_users():
    """Search users by email domain. Internal use only."""
    domain = request.args.get('domain', '')
    if not domain or len(domain) > 128:
        return jsonify({'error': 'Invalid domain'}), 400

    sanitized = sanitize_input(domain)
    if sanitized is None:
        return jsonify({'error': 'Invalid characters'}), 400

    normalized = normalize_username(sanitized)

    db = get_db()
    try:
        query = f"SELECT username, email FROM users WHERE email LIKE '%@{normalized}'"
        results = db.execute(query).fetchall()
        return jsonify({'users': [{'username': r['username'], 'email': r['email']} for r in results]})
    except Exception as e:
        return jsonify({'error': 'Database error'}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
